  void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(!e.Source.StartsWith("https://studio.local/Assets/Web/",StringComparison.OrdinalIgnoreCase))return;try{var message=JObject.Parse(e.WebMessageAsJson);string action=(string)message["action"];if(action=="previewStats"){previewFps=Math.Max(0,Math.Min(120,(double?)message["fps"]??0));return;}if(action=="page"){previewPage=(string)message["page"]=="display";return;}HandleMessage(message);}catch(Exception ex){Post(new{type="error",message=ex.Message});}}
  async void HandleMessage(JObject message){string action=(string)message["action"]??"";try{if(busy&&action!="stop"&&action!="saveSettings")return;switch(action){
